<script setup lang="ts">import {onMounted,ref} from 'vue'; import {useRouter} from 'vue-router'; const router=useRouter(); const name=ref(''),email=ref(''),password=ref(''),error=ref(''),environment=ref<any>({});onMounted(async()=>{environment.value=(await (await fetch('/api/v1/setup/status')).json()).infrastructure||{}}); async function submit(){const r=await fetch('/api/v1/setup/admin',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:name.value,email:email.value,password:password.value})});if(r.ok)router.push('/');else error.value='Revise os dados informados.'}</script>
<template><div class="center"><p class="kicker">WELCOME TO STACKHOST</p><h1>Build your control plane.</h1><p class="muted">Create the first administrator to get started.</p><div class="status"><span class="dot"></span><div><strong>{{environment.available?'Docker connected':'Docker optional'}}</strong><p>{{environment.available?`Docker ${environment.engine_version} detected`:'You can continue without Docker and connect it later.'}}</p></div></div><form @submit.prevent="submit"><label>Name<input v-model="name" required /></label><label>Email<input v-model="email" type="email" required /></label><label>Password<input v-model="password" type="password" minlength="8" required /></label><p class="error">{{error}}</p><button class="primary">Create administrator</button></form></div></template>
